// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 sendAmount, uint256 warpTimestamp, uint64 blockNum) public {
        vm.assume(sendAmount == 10 ether);
        vm.assume(warpTimestamp > 0);
        vm.assume(blockNum >= 1);
        vm.assume(warpTimestamp > c.pastBlockTime());
        vm.warp(warpTimestamp);
        vm.roll(blockNum);
        address actor = address(0x1234);
        vm.deal(actor, 20 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: sendAmount}("");
        require(ok, "call must not revert");
        assertTrue(c.pastBlockTime() == warpTimestamp);
    }
}
